INSERT INTO "public"."chat_history" ("id", "user_id", "message", "is_ai", "created_at") VALUES
	('b562ce17-0460-4f81-a2ec-4082513331d7', 'c1135bce-1f99-4ab3-b832-158ef0070db1', 'Tell me about my goals', false, '2025-01-24 17:04:52.337732+00'),
	('def1fa92-2d47-4196-8010-77b1f65ff0bc', 'c1135bce-1f99-4ab3-b832-158ef0070db1', 'Your goals are to stay in touch and reconnect with others, make new friends, and try new activities. These goals reflect a desire to strengthen your social connections and explore new experiences. If you''d like, I can help you brainstorm ideas or activities to achieve these goals!', true, '2025-01-24 17:04:54.90119+00'),
	('8ac8856e-84e6-4061-b0d2-2e1fab52bca7', 'bd6c423b-47cb-4bc5-a36c-67ad0fbe9728', 'What did we talk about last time?', false, '2025-01-24 17:06:06.603423+00'),
	('0ff12ed1-7395-49c1-a801-a97291569797', 'bd6c423b-47cb-4bc5-a36c-67ad0fbe9728', 'It looks like there isn''t any recent chat history to refer to. But I''m here to help you with anything you''d like to discuss now! Whether it''s about staying in touch with friends, making new connections, or exploring your interests, just let me know!', true, '2025-01-24 17:06:08.194531+00'),
	('244a9e3b-8a92-44c2-b7db-006a89beeabc', 'c1135bce-1f99-4ab3-b832-158ef0070db1', 'Tell me about my upcoming calendar events', false, '2025-01-24 17:15:14.504325+00'),
	('01ebed93-4a56-43b5-ae90-337a806f97a0', 'c1135bce-1f99-4ab3-b832-158ef0070db1', 'I''m sorry, Simon, but currently, there are no upcoming events in your calendar. Would you like some help in planning some new activities that align with your goals of trying new things, making new friends, and reconnecting with others?', true, '2025-01-24 17:15:18.754825+00'),
	('56028de6-a460-4660-8c87-d73388730232', 'c1135bce-1f99-4ab3-b832-158ef0070db1', 'I want to Get sushi with Rei at Friday', false, '2025-01-24 19:37:30.871651+00'),
